THOUGHT: Ah, now I see another issue! The pydantic dataclass is not accepting the `baz` parameter in the constructor, which means it's not treating it as an init_var field correctly.

Let me modify the test to use keyword arguments:

```bash
cat <<'EOF' > compare_behavior_kwargs.py
import pydantic
from pydantic import Field
import dataclasses
from dataclasses import InitVar

# Standard library dataclass
@dataclasses.dataclass
class StdLibFoo:
    bar: str
    baz: InitVar[str]

# Pydantic dataclass
@pydantic.dataclasses.dataclass
class PydanticFoo:
    bar: str
    baz: str = Field(init_var=True)

print("=== Standard Library Dataclass ===")
try:
    std_instance = StdLibFoo('bar_value', 'baz_value')  # Positional args
    print(f"std_instance.bar = {std_instance.bar}")
    try:
        print(f"std_instance.baz = {std_instance.baz}")
    except AttributeError as e:
        print(f"Expected error accessing baz: {e}")
except Exception as e:
    print(f"Error with stdlib dataclass: {e}")

print("\n=== Pydantic Dataclass ===")
try:
    pyd_instance = PydanticFoo(bar='bar_value', baz='baz_value')  # Keyword args
    print(f"pyd_instance.bar = {pyd_instance.bar}")
    try:
        print(f"pyd_instance.baz = {pyd_instance.baz}")
    except AttributeError as e:
        print(f"Expected error accessing baz: {e}")
    except Exception as e:
        print(f"Other error accessing baz: {e}")
except Exception as e:
    print(f"Error with pydantic dataclass: {e}")
EOF
```

